-- 临床模板库 P1a 开发样例：全院医嘱组套（一条药品、一条检验项目），便于验收组套的读取、默认勾选与执行科室。
insert into RHN_META_OP_PLAN_TMPL (ID_OP_PLAN_TMPL, REVISION, ID_TNT, ID_ORG, ID_DEPT, SD_SCOPE_TYPE, ID_OWNER, NA_TMPL, DES_OP_PLAN_TMPL, SD_STATUS, SN_SORT, QTY_USE, SD_SOURCE_TYPE, SD_TMPL_KIND, ID_USER_CREATED, DT_CREATED, ID_USER_UPDATED, DT_UPDATED)
select 362387896013000, 0, 362387869790209, 362387869790211, 362387869899101, 'HOSPITAL', 362387869790211, '血常规复查组套', '复查血常规并附加一种常用药品，药品默认不勾选', 'ACTIVE', 900, 0, 'MANUAL', 'ORDER_SET', 362387869790222, current_timestamp, 362387869790222, current_timestamp from dual
where not exists (select 1 from RHN_META_OP_PLAN_TMPL where ID_OP_PLAN_TMPL = 362387896013000)
  and exists (select 1 from RHN_SYS_DEPT where ID_TNT = 362387869790209 and ID_ORG = 362387869790211 and ID_DEPT = 362387869899101);

insert into RHN_META_OP_PLAN_MED (ID_OP_PLAN_MED, ID_TNT, ID_OP_PLAN_TMPL, SN_LINE, ID_MED, CD_CAT, CD_MED, NA_MED, PREP_SPEC, QTY_ORDERED, QTY_UNIT, FG_SUBSTN, FG_SELF_PRVDD, FG_PRICING_RQD, SD_PRICE_TYPE, FG_DEFAULT_SELCTD)
select 362387896013001, 362387869790209, 362387896013000, 1, m.ID_MED, m.SD_MED_TYPE, m.CD_MED, m.NA_MED, m.PREP_SPEC, 1, m.PREP_UNIT, 0, 0, 1, 'SALE', 0
from RHN_BD_MED m
where m.ID_MED = (select min(x.ID_MED) from RHN_BD_MED x where x.ID_TNT = 362387869790209 and x.SD_STATUS = 'ACTIVE' and x.SD_MED_TYPE <> 'HERBAL')
  and exists (select 1 from RHN_META_OP_PLAN_TMPL where ID_OP_PLAN_TMPL = 362387896013000)
  and not exists (select 1 from RHN_META_OP_PLAN_MED where ID_OP_PLAN_MED = 362387896013001);

insert into RHN_META_OP_PLAN_SVC (ID_OP_PLAN_SVC, ID_TNT, ID_OP_PLAN_TMPL, SN_LINE, ID_CATALOG_ITEM, CD_ITEM, NA_ITEM, SD_SVC_TYPE, QTY_ORDERED, CD_UNIT, SD_PRICE_TYPE, FG_PRICING_RQD, FG_DEFAULT_SELCTD, ID_DEPT_EXEC)
select 362387896013002, 362387869790209, 362387896013000, 1, c.ID_CATALOG_ITEM, c.CD_CATALOG_ITEM, c.NA_CATALOG_ITEM, s.SD_SVC_TYPE, 1, c.CD_UNIT, 'SALE', 1, 1, 362387869899101
from RHN_BD_CATALOG_ITEM c join RHN_BD_SVC_ITEM s on s.ID_CATALOG_ITEM = c.ID_CATALOG_ITEM and s.ID_TNT = c.ID_TNT
where c.ID_TNT = 362387869790209 and c.CD_CATALOG_ITEM = '25010100100' and c.SD_STATUS = 'ACTIVE'
  and exists (select 1 from RHN_META_OP_PLAN_TMPL where ID_OP_PLAN_TMPL = 362387896013000)
  and not exists (select 1 from RHN_META_OP_PLAN_SVC where ID_OP_PLAN_SVC = 362387896013002);
